/**
 * iterutils.mjs — a faithful JavaScript port of the two `boltons.iterutils`
 * helpers used by the script: `partition` and `bucketize`.
 *
 * Design notes:
 *  - Both helpers consume *any* iterable exactly once and never mutate it.
 *  - `bucketize` returns a `Map` rather than a plain object: a `Map` preserves
 *    first-occurrence key insertion order for arbitrary key types (booleans
 *    included), which is precisely what a Python `dict` does. A plain object
 *    would stringify the keys and lose that fidelity.
 *  - The default key function is `pyBool`, the Python truthiness rule, so that
 *    `partition(src)` / `bucketize(src)` behave like their `bool`-keyed Python
 *    counterparts.
 */

import { PyTuple } from './pyrepr.mjs';

/**
 * Python truthiness (`bool(x)`).
 *
 * Falsy: `false`, `null`/`undefined` (Python `None`), numeric zero, `0n`, the
 * empty string, the empty array (`[]`), and empty `Map`/`Set` (`{}` / `set()`).
 * Everything else is truthy — including `NaN`, which is truthy in Python even
 * though it is falsy under JavaScript's own coercion rules.
 *
 * @param {unknown} x
 * @returns {boolean}
 */
export function pyBool(x) {
  if (x === null || x === undefined || x === false) return false;
  if (x === true) return true;

  switch (typeof x) {
    case 'number':
      return x !== 0; // NaN -> true, matching Python's float('nan')
    case 'bigint':
      return x !== 0n;
    case 'string':
      return x.length > 0;
    default:
      break;
  }

  if (Array.isArray(x)) return x.length > 0; // list/tuple
  if (x instanceof Map || x instanceof Set) return x.size > 0; // dict/set
  return true; // any other object is truthy
}

/**
 * A terse, Python-`repr`-ish rendering of a value, used only inside the
 * TypeError messages below. Deliberately local so this module needs nothing
 * from `pyrepr.mjs` beyond `PyTuple`.
 *
 * @param {unknown} value
 * @returns {string}
 */
function describe(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'function') return `function ${value.name || '<anonymous>'}`;
  if (value === null) return 'null';
  return `${typeof value} ${String(value)}`;
}

/**
 * Resolve the `key` argument into a callable, mirroring boltons: a function is
 * used as-is, and a string is treated as an attribute/property getter that
 * falls back to the element itself when the property is absent (Python's
 * `getattr(x, key, x)`).
 *
 * @param {Function|string} key
 * @returns {(value: any) => any}
 */
function toKeyFunc(key) {
  if (typeof key === 'function') return key;

  if (typeof key === 'string') {
    return (value) => {
      if (value === null || value === undefined) return value;
      const obj = Object(value); // box primitives so `in` works on them
      return key in obj ? obj[key] : value;
    };
  }

  throw new TypeError(`expected callable or string, not ${describe(key)}`);
}

/**
 * Assert that `src` can be iterated, then hand back the iterable unchanged.
 *
 * @param {Iterable<any>} src
 * @returns {Iterable<any>}
 */
function checkIterable(src) {
  if (src === null || src === undefined || typeof src[Symbol.iterator] !== 'function') {
    throw new TypeError(`expected an iterable src, not ${describe(src)}`);
  }
  return src;
}

/**
 * Build the 2-tuple returned by `partition`.
 *
 * `PyTuple` is defined in a sibling module, so tolerate either reasonable
 * shape: a wrapper constructed from a list of items, or an `Array` subclass
 * (whose inherited constructor has single-argument semantics that would
 * otherwise nest the pair inside another array).
 *
 * @param {any[]} items
 * @returns {PyTuple}
 */
function makePyTuple(items) {
  const proto = PyTuple.prototype;
  if (proto instanceof Array || proto === Array.prototype) {
    return typeof PyTuple.from === 'function' ? PyTuple.from(items) : new PyTuple(...items);
  }
  return new PyTuple(items);
}

/**
 * `boltons.iterutils.partition(src, key=bool)`
 *
 * Split `src` into two lists: elements whose key is truthy come first.
 * Relative order is preserved within each list.
 *
 *   partition([1, 2, 3, 4], x => x % 2 === 0)  ->  ([2, 4], [1, 3])
 *
 * @param {Iterable<any>} src   any iterable; it is not mutated
 * @param {Function|string} [key=pyBool]
 * @returns {PyTuple} a 2-tuple of `[trues, falses]`
 */
export function partition(src, key = pyBool) {
  const keyFunc = toKeyFunc(key);
  const trues = [];
  const falses = [];

  for (const value of checkIterable(src)) {
    // Python-truthiness of the key result decides the bucket. (boltons routes
    // this through `bucketize(...).get(True)`, which works there only because
    // Python hashes `True` and `1` identically; a JS `Map` does not, so the
    // truthiness test is applied directly here.)
    (pyBool(keyFunc(value)) ? trues : falses).push(value);
  }

  return makePyTuple([trues, falses]);
}

/**
 * `boltons.iterutils.bucketize(src, key=bool, value_transform=None,
 * key_filter=None)`
 *
 * Group the elements of `src` by `key(element)`. Keys appear in the order they
 * are first produced and each bucket keeps the original element order, exactly
 * like the Python dict boltons builds.
 *
 *   bucketize([2, 1, 3], x => x % 2 === 0)  ->  Map { true => [2], false => [1, 3] }
 *
 * A `Map` compares keys with SameValueZero, so `true`/`false` (and `0`/`-0`)
 * collapse the same way Python's dict keys do.
 *
 * @param {Iterable<any>} src   any iterable; it is not mutated
 * @param {Function|string} [key=pyBool]
 * @param {object} [options]
 * @param {Function|null} [options.valueTransform] applied to each element before it is stored
 * @param {Function|null} [options.keyFilter] keys for which this returns falsy are dropped
 * @returns {Map<any, any[]>}
 */
export function bucketize(src, key = pyBool, { valueTransform = null, keyFilter = null } = {}) {
  const keyFunc = toKeyFunc(key);

  if (valueTransform !== null && valueTransform !== undefined && typeof valueTransform !== 'function') {
    throw new TypeError(`expected callable value transform function, not ${describe(valueTransform)}`);
  }
  if (keyFilter !== null && keyFilter !== undefined && typeof keyFilter !== 'function') {
    throw new TypeError(`expected callable key filter function, not ${describe(keyFilter)}`);
  }

  const transform = typeof valueTransform === 'function' ? valueTransform : (x) => x;
  const buckets = new Map();

  for (const value of checkIterable(src)) {
    const bucketKey = keyFunc(value);
    if (keyFilter !== null && keyFilter !== undefined && !pyBool(keyFilter(bucketKey))) continue;

    let bucket = buckets.get(bucketKey);
    if (bucket === undefined) {
      bucket = [];
      buckets.set(bucketKey, bucket); // first occurrence fixes the key order
    }
    bucket.push(transform(value));
  }

  return buckets;
}

